2360	    const std::shared_ptr<arrow::Schema> &result_schema,
2361	    const std::vector<int> &segment_doc_ids) const {
2362	  std::vector<std::shared_ptr<arrow::ChunkedArray>> chunk_arrays;
2363	  chunk_arrays.resize(columns.size());
2364	
2365	  bool has_segment_row_id_column = false;
2366	  size_t segment_row_id_col_index = 0;
2367	
2368	  for (size_t i = 0; i < columns.size(); ++i) {
2369	    if (columns[i] == LOCAL_ROW_ID) {
