2379	
2380	  // Parallel to segment_doc_ids: each pair is (chunk_index, row_index_in_chunk)
2381	  std::vector<std::pair<int64_t, int64_t>> chunk_row_indices_for_ids;
2382	  for (const auto segment_doc_id : segment_doc_ids) {
2383	    auto it = std::upper_bound(chunk_offsets_.begin(), chunk_offsets_.end(),
2384	                               segment_doc_id);
