2386	      LOG_ERROR("Segment doc ID %d is out of bounds", segment_doc_id);
2387	      return nullptr;
2388	    }
2389	    int chunk_index =
2390	        static_cast<int>(std::distance(chunk_offsets_.begin(), it) - 1);
2391	    int64_t row_index_in_chunk = segment_doc_id - chunk_offsets_[chunk_index];
2392	    chunk_row_indices_for_ids.emplace_back(chunk_index, row_index_in_chunk);
2393	  }
2394	
