1772	      if (vector_index_params->quantize_type() == QuantizeType::RABITQ) {
1773	        raw_vector_provider = vector_indexer.value()->create_index_provider();
1774	      }
1775	    } else {
1776	      raw_vector_provider =
1777	          vector_indexers_[column][0]->create_index_provider();
1778	    }
1779	
1780	    auto field_with_new_index_params = std::make_shared<FieldSchema>(*field);
1781	    field_with_new_index_params->set_index_params(index_params);
1782	
1783	    // For RABITQ, PrepareQuantizeField trains a reformer with
1784	    // raw_vector_provider and attaches it to a cloned HnswRabitqIndexParams.
1785	    // For other quantize types, field_with_new_index_params is reused as-is.
1786	    std::shared_ptr<FieldSchema> field_for_quantize;
1787	    {
1788	      auto s = SegmentHelper::PrepareQuantizeField(*field_with_new_index_params,
1789	                                                   raw_vector_provider,
1790	                                                   &field_for_quantize);
1791	      CHECK_RETURN_STATUS(s);
1792	    }
1793	
1794	    auto quant_block_id = allocate_block_id();
1795	    std::string index_file_path = FileHelper::MakeQuantizeVectorIndexPath(
1796	        path_, column, segment_meta_->id(), quant_block_id);
1797	    if (FileHelper::FileExists(index_file_path)) {
1798	      LOG_WARN(
1799	          "Index file[%s] already exists (possible crash residue); cleaning "
1800	          "and overwriting.",
1801	          index_file_path.c_str());
1802	      FileHelper::RemoveFile(index_file_path);
1803	    }
1804	    auto vector_indexer = merge_vector_indexer(
1805	        index_file_path, column, *field_for_quantize, concurrency);
1806	    if (!vector_indexer.has_value()) {
1807	      return vector_indexer.error();
1808	    }
1809	
1810	    quant_vector_indexers->insert({column, vector_indexer.value()});
1811	
1812	    new_segment_meta->remove_vector_persisted_block(column, true);
1813	    BlockMeta block;
1814	    block.set_id(quant_block_id);
1815	    block.set_type(BlockType::VECTOR_INDEX_QUANTIZE);
1816	    block.set_columns({column});
1817	    block.set_min_doc_id(meta()->min_doc_id());
1818	    block.set_max_doc_id(meta()->max_doc_id());
1819	    block.set_doc_count(meta()->doc_count());
1820	    new_segment_meta->add_persisted_block(block);
1821	
1822	    *segment_meta = new_segment_meta;
1823	  }
1824	
1825	  return Status::OK();
1826	}
