98	  if (!opened_) {
99	    return Status::InternalError();
100	  }
101	
102	  rocksdb::Slice value((const char *)&doc_id, sizeof(uint64_t));
103	  auto s = rocksdb_context_.db_->Put(rocksdb_context_.write_opts_, key, value);
104	  if (s.ok()) {
105	    return Status::OK();
106	  } else {
107	    LOG_ERROR("Failed to put [%s, %zu] into IDMap[%s], code[%d], reason[%s]",
108	              key.c_str(), (size_t)doc_id, working_dir_.c_str(), s.code(),
109	              s.ToString().c_str());
110	    return Status::InternalError();
111	  }
