121	  std::string value;
122	  auto s = rocksdb_context_.db_->Get(rocksdb_context_.read_opts_, key, &value);
123	  if (s.ok()) {
124	    if (doc_id) {
125	      *doc_id = *(uint64_t *)(value.data());
126	    }
127	    return true;
128	  } else {
129	    if (doc_id) {
130	      *doc_id = INVALID_DOC_ID;
131	    }
132	    return false;
133	  }
