137	Status IDMap::multi_get(const std::vector<std::string> &keys,
138	                        std::vector<uint64_t> *doc_ids) const {
139	  if (keys.empty()) {
140	    doc_ids->clear();
141	    return Status::InvalidArgument();
142	  }
143	
144	  std::vector<rocksdb::Slice> slice_keys(keys.begin(), keys.end());
145	  std::vector<rocksdb::PinnableSlice> pinnable_values;
146	  pinnable_values.resize(keys.size());
147	  std::vector<rocksdb::Status> statuses;
148	  statuses.resize(keys.size());
149	
150	  auto db = rocksdb_context_.db_.get();
151	
152	  db->MultiGet(rocksdb_context_.read_opts_, db->DefaultColumnFamily(),
153	               slice_keys.size(), slice_keys.data(), pinnable_values.data(),
154	               statuses.data(), false);
155	
156	  doc_ids->resize(keys.size());
157	  for (size_t i = 0; i < keys.size(); i++) {
158	    if (statuses[i].ok()) {
159	      (*doc_ids)[i] = *(uint64_t *)(pinnable_values[i].data());
160	    } else if (statuses[i].code() == rocksdb::Status::kNotFound) {
161	      (*doc_ids)[i] = INVALID_DOC_ID;
162	    } else {
163	      LOG_ERROR("Failed to get key[%s] from IDMap[%s], code[%d], reason[%s]",
164	                keys[i].c_str(), working_dir_.c_str(), statuses[i].code(),
165	                statuses[i].ToString().c_str());
166	      return Status::InternalError();
167	    }
168	  }
169	
170	  return Status::OK();
171	}
